'use client';
import { useState } from 'react';
import useSWR from 'swr';

interface Project {
  id: string;
  name: string;
  status: 'active' | 'paused' | 'archived';
  lastRun: string;
  passRate: number;
}

const fetcher = (url: string) => fetch(url).then(r => r.json());

export function ProjectsTable({ userId }: { userId: string }) {
  const [filter, setFilter] = useState<string>('');
  const { data: projects = [], isLoading } = useSWR<Project[]>(
    `/api/projects?userId=${userId}`,
    fetcher
  );

  const filtered = projects.filter(p =>
    p.name.toLowerCase().includes(filter.toLowerCase())
  );

  if (isLoading) return <div className="animate-pulse h-48 bg-muted rounded" />;

  return (
    <div className="border rounded-lg">
      <div className="p-4 border-b">
        <input
          type="search"
          placeholder="Filter projects..."
          value={filter}
          onChange={e => setFilter(e.target.value)}
          className="w-full px-3 py-2 border rounded"
          data-testid="project-filter"
        />
      </div>
      <table className="w-full">
        <thead>
          <tr className="border-b bg-muted/50">
            <th className="text-left p-3">Name</th>
            <th className="text-left p-3">Status</th>
            <th className="text-right p-3">Pass Rate</th>
          </tr>
        </thead>
        <tbody>
          {filtered.map(project => (
            <tr key={project.id} className="border-b hover:bg-muted/30">
              <td className="p-3"><a href={`/projects/${project.id}`}>{project.name}</a></td>
              <td className="p-3"><span className={`badge badge-${project.status}`}>{project.status}</span></td>
              <td className="p-3 text-right font-mono">{project.passRate}%</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
